process_prompt(processor, llm: LLM, question: str,
                   image_urls: list[Image]):
    """
    Form the prompt based on the text and image input, then llm generate output
    """
    placeholders = [{
        "type": "image_url",
        "image_url": {
            "url": f"data:image;base64,{encode_image_base64(image_pil)}"
        }
    } for image_pil in image_urls]

    messages = [
        {
            "role": "system",
            "content": "You are a helpful assistant."
        },
        {
            "role": "user",
            "content": [
                *placeholders,
                {
                    "type": "text",
                    "text": question
                },
            ],
        },
    ]

    prompt = processor.apply_chat_template(messages,
                                           tokenize=False,
                                           add_generation_prompt=True)

    outputs = llm.generate(
        {
            "prompt":
            prompt,
            **({
                "multi_modal_data": {
                    "image": [*image_urls]
                }
            } if image_urls else {})
        },
        sampling_params=SAMPLING_PARAMS,
    )

    print("-" * 50)
    print("Output:")
    for o in outputs:
        generated_text = o.outputs[0].text
        print(generated_text)
        print("-" * 50)


